-- Canonical Entity Autocomplete System — Drive corpus import (entity batch 1).
-- Source: "ORYN Canonical App Data Pack — Verified 2026-08-15" (Google Sheet, ORYN Database Drive folder) —
-- the current, non-superseded canonical data pack. Generated by
-- scripts/drive-import/parse_entities.py + generate_entities_sql.py; see
-- scripts/drive-import/README.md for the process and docs/entity-canonicalization-audit.md
-- for what this batch does and does not attempt.
--
-- Requires supabase/migrations/0038_canonical_institutions.sql applied first (this
-- file's ON CONFLICT clauses depend on its unique indexes). Not applied to any live
-- database this session — see docs/founder-blocked-backlog.md item 17.
--
-- Idempotent: every insert/update is safe to re-run.

-- ---------- Organizations (PROV, 19 rows, all release_state=VERIFIED) ----------
on conflict (category, lower(canonical_name), coalesce(country, ''), coalesce(city, '')) do nothing;

-- ---------- Schools (TRSCH, 54 of 58 rows — 4 excluded: release_state starts with HOLD_, not yet safe to surface) ----------
on conflict (category, lower(canonical_name), coalesce(country, ''), coalesce(city, '')) do nothing;

-- ---------- Universities (GUNI, QS 2027 ranking — 77 new of 98, 21 already exist in supabase/seed.sql + seed_drive_batch1.sql by name+country match) ----------
on conflict (lower(name), country) do nothing;

-- Alias enrichment for 3 already-existing universities (explicit parenthetical abbreviation in the source, e.g. "(MIT)")
update public.universities set aliases = array_append(aliases, 'MIT') where lower(name) = lower('Massachusetts Institute of Technology') and country = 'United States' and not ('MIT' = any(aliases));
update public.universities set aliases = array_append(aliases, 'UCB') where lower(name) = lower('University of California, Berkeley') and country = 'United States' and not ('UCB' = any(aliases));
update public.universities set aliases = array_append(aliases, 'NYU') where lower(name) = lower('New York University') and country = 'United States' and not ('NYU' = any(aliases));

-- ---------- Opportunity aliases (5 of 7 usable — 2 excluded: canonical_opportunity_id not in the 16-row official-current set) ----------
-- Matched by exact title — a safe no-op if this batch's existing `opportunities` rows
-- use a differently-worded title than this corpus's own canonical name; never guesses.
update public.opportunities set aliases = array_append(aliases, '67th London International Youth Science Forum (LIYSF) - 2026') where title = 'London International Youth Science Forum (LIYSF) 2027' and not ('67th London International Youth Science Forum (LIYSF) - 2026' = any(aliases));
update public.opportunities set aliases = array_append(aliases, 'HMMT') where title = 'HMMT Season 30 — November 2026 / February 2027' and not ('HMMT' = any(aliases));
update public.opportunities set aliases = array_append(aliases, 'The Earth Prize Competition') where title = 'The Earth Prize 2027' and not ('The Earth Prize Competition' = any(aliases));
update public.opportunities set aliases = array_append(aliases, 'Wharton Global High School Investment Competition') where title = 'Wharton Global High School Investment Competition 2026-2027' and not ('Wharton Global High School Investment Competition' = any(aliases));
update public.opportunities set aliases = array_append(aliases, 'AMC - AIME') where title = 'MAA AMC 10 / AMC 12 2026-2027' and not ('AMC - AIME' = any(aliases));
